// Short UI sounds (generated by assets/sounds/make-sfx.mjs). Played only inside the wake-up flow:
// the app's audio session plays through the silent switch (alarms must), so a ting anywhere else would too.
import { createAudioPlayer, type AudioPlayer } from 'expo-audio';

const SOURCES = {
    /** A right answer, the last step: something positive just happened. */
    ting: require('../assets/sounds/sfx_ting.wav'),
    /** Today's flame lights up on the +1 screen. */
    fire: require('../assets/sounds/sfx_fire.wav'),
} as const;
export type Sfx = keyof typeof SOURCES;

const players: Partial<Record<Sfx, AudioPlayer>> = {};

/** Load them ahead, so the first one plays on the frame it's asked for. */
export function preloadSfx(): void {
    (Object.keys(SOURCES) as Sfx[]).forEach(name => {
        try {
            players[name] ??= createAudioPlayer(SOURCES[name]);
        } catch {
            // no audio (web, tests): stay silent
        }
    });
}

export function sfx(name: Sfx): void {
    try {
        const player = (players[name] ??= createAudioPlayer(SOURCES[name]));
        player.volume = 0.7;
        player.seekTo(0).catch(() => {});
        player.play();
    } catch {
        // never let a sound effect break the flow
    }
}
